ole']==='User'?'selected':'' ?>>User</option><option value="Admin" <?= $listed['role']==='Admin'?'selected':'' ?>>Admin</option></select></form><?php else: ?>Admin<?php endif; ?></td><td><?php if((int)$listed['id']!==(int)$admin['id']): ?><button class="btn btn-sm btn-danger block_user_btn" style="<?= (int)$listed['ac_status']===2?'display:none':'' ?>" data-user-id="<?= (int)$listed['id'] ?>">Chặn</button><button class="btn btn-sm btn-success unblock_user_btn" style="<?= (int)$listed['ac_status']===2?'':'display:none' ?>" data-user-id="<?= (int)$listed['id'] ?>">Mở chặn</button> <a class="btn btn-sm btn-info" href="?action=user_login&email=<?= rawurlencode($listed['email']) ?>">Đăng nhập</a> <form method="post" action="?action=delete_user" class="d-inline" onsubmit="return confirm('Xóa người dùng này?')"><input type="hidden" name="id" value="<?= (int)$listed['id'] ?>"><button class="btn btn-sm btn-outline-danger">Xóa</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php endif; ?>
